def sd_calc(data):
    import math

    n = len(data)

    if n < 2:
        return float('nan')

    mean = sum(data) / n

    sum_sq_diff = 0
    for x in data:
        sum_sq_diff += (x - mean) ** 2

    variance = sum_sq_diff / (n - 1)

    std_dev = math.sqrt(variance)

    return std_dev

