def check_subset(list1, list2):
    def _are_equal_nested(a, b):
        # If types are different, they are not equal (e.g., 1 vs [1])
        if type(a) != type(b):
            return False

        # If they are not lists, compare directly
        if not isinstance(a, list):
            return a == b

        # Both are lists, compare their lengths
        if len(a) != len(b):
            return False

        # Recursively compare elements
        for x, y in zip(a, b):
            if not _are_equal_nested(x, y):
                return False
        return True

    # If list1 is empty, it's a subset of any list2
    if not list1:
        return True

    # Create a mutable copy of list2 to "consume" elements
    # This allows handling duplicate elements correctly.
    temp_list2 = list(list2)

    for item1 in list1:
        found_match = False
        # Iterate using index to allow efficient removal with pop()
        for i in range(len(temp_list2)):
            item2 = temp_list2[i]
            if _are_equal_nested(item1, item2):
                found_match = True
                # Remove the matched element from temp_list2 to handle duplicates
                temp_list2.pop(i)
                break  # Found a match for item1, move to the next item1
        if not found_match:
            return False  # An element from list1 was not found in list2

    return True  # All elements from list1 were found and consumed from list2

