        start = 0
        while start < k:
            sub_arr[start], sub_arr[k] = sub_arr[k], sub_arr[start]
            start += 1
            k -= 1

    for i in range(n - 1, 0, -1):
        max_val = arr[0]
        max_idx = 0
        for j in range(1, i + 1):
            if arr[j] > max_val:
                max_val = arr[j]
                max_idx = j

        if max_idx != i:
            if max_idx != 0:
                _flip(arr, max_idx)

            _flip(arr, i)

    return arr

