def roman_to_int(s: str) -> int:
    roman_map = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }
    total = 0
    n = len(s)

    for i in range(n):
        current_val = roman_map[s[i]]
        # If the current numeral is smaller than the next numeral,
        # it means we have a subtractive case (e.g., IV, IX, XL, etc.)
        # In such cases, we subtract the current value.
        if i + 1 < n and current_val < roman_map[s[i+1]]:
            total -= current_val
        # Otherwise, we add the current value.
        else:
            total += current_val

    return total

