def find_even_Pair(arr):
    count_even = 0
    count_odd = 0
    for num in arr:
        if num % 2 == 0:
            count_even += 1
        else:
            count_odd += 1

    # Number of pairs from even numbers: C(n, 2) = n * (n - 1) / 2
    pairs_from_even = (count_even * (count_even - 1)) // 2 

    # Number of pairs from odd numbers: C(n, 2) = n * (n - 1) / 2
    pairs_from_odd = (count_odd * (count_odd - 1)) // 2

    return pairs_from_even + pairs_from_odd

def find_even_Pair(A, N):
    evenPair = 0
    for i in range(N):
        for j in range(i + 1, N):
            if ((A[i] ^ A[j]) % 2 == 0):
                evenPair += 1
    return evenPair

