def sum_Of_product(m, n, r):
    def nCr(n_val, r_val):
        if r_val < 0 or r_val > n_val:
            return 0
        if r_val == 0 or r_val == n_val:
            return 1
        if r_val > n_val // 2:
            r_val = n_val - r_val

        res = 1
        for i in range(r_val):
            res = res * (n_val - i) // (i + 1)
        return res

    total_sum = 0
    for k in range(r + 1):
        term1 = nCr(m, k)
        term2 = nCr(n, r - k)
        total_sum += term1 * term2
    return total_sum

