def max_len_sub(arr):
    n = len(arr)
    if n == 0:
        return 0

    # dp[i] stores the length of the longest subsequence ending at arr[i]
    # where the absolute difference between adjacent elements is 1.
    # Initialize all lengths to 1, as each element itself is a subsequence of length 1.
    dp = [1] * n

    # Iterate through each element of the array
    for i in range(n):
        # For each element arr[i], check all previous elements arr[j]
        for j in range(i):
            # If arr[j] can be the element immediately preceding arr[i]
            # in a valid subsequence (i.e., their absolute difference is 1)
            if abs(arr[i] - arr[j]) == 1:
                # Update dp[i] if we can form a longer subsequence ending at arr[i]
                # by appending arr[i] to a subsequence ending at arr[j].
                dp[i] = max(dp[i], dp[j] + 1)

    # The maximum value in the dp array will be the maximum length of any such subsequence.
    return max(dp)

