def max_profit(k, prices):
    n = len(prices)

    if n == 0 or k == 0:
        return 0

    if k >= n // 2:
        max_prof = 0
        for i in range(1, n):
            if prices[i] > prices[i-1]:
                max_prof += prices[i] - prices[i-1]
        return max_prof

    dp_prev_trans = [0] * n
    dp_curr_trans = [0] * n

    for i in range(1, k + 1):
        max_diff = -prices[0]

        for j in range(1, n):
            dp_curr_trans[j] = dp_curr_trans[j-1]
            dp_curr_trans[j] = max(dp_curr_trans[j], prices[j] + max_diff)
            max_diff = max(max_diff, dp_prev_trans[j] - prices[j])

        dp_prev_trans = list(dp_curr_trans)

    return dp_curr_trans[n-1]

