        inc_sum[i] = arr[i]  # A single element is an increasing subsequence
        for j in range(i):
            if arr[j] < arr[i]:
                inc_sum[i] = max(inc_sum[i], arr[i] + inc_sum[j])

    # dec_sum[i] stores the maximum sum of a decreasing subsequence starting at arr[i]
    # (or ending at arr[i] if we iterate from right to left)
    dec_sum = [0] * n
    for i in range(n - 1, -1, -1):
        dec_sum[i] = arr[i]  # A single element is a decreasing subsequence
        for j in range(i + 1, n):
            if arr[j] < arr[i]:
                dec_sum[i] = max(dec_sum[i], arr[i] + dec_sum[j])

    # Calculate the maximum sum of a bi-tonic subsequence
    # For each element arr[i] considered as the peak,
    # the sum is inc_sum[i] + dec_sum[i] - arr[i].
