def count_Fac(n):
    if n <= 1:
        return 0

    distinct_prime_factors = set()

    # Handle factor 2
    if n % 2 == 0:
        distinct_prime_factors.add(2)
        while n % 2 == 0:
            n //= 2

    # Handle odd factors
    # We only need to check up to sqrt(n)
    i = 3
    while i * i <= n:
        if n % i == 0:
            distinct_prime_factors.add(i)
            while n % i == 0:
                n //= i
        i += 2 # Only check odd numbers

    # If n is still greater than 1, it must be a prime factor itself
    if n > 1:
