        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                s += i
                if i * i != n:
                    s += n // i
        return s

    total_sum = 0
    processed_numbers = set()

    for n in range(1, limit + 1):
        if n in processed_numbers:
            continue

        sum_div_n = sum_proper_divisors(n)

        if sum_div_n > 0 and sum_div_n != n and sum_div_n <= limit:
            sum_div_sum_div_n = sum_proper_divisors(sum_div_n)

            if sum_div_sum_div_n == n:
