def amicable_numbers_sum(limit):
    import math

    def sum_proper_divisors(n):
        if n <= 1:
            return 0
        s = 1
        sqrt_n = int(math.sqrt(n))
        for i in range(2, sqrt_n + 1):
            if n % i == 0:
                s += i
                if i * i != n:
                    s += (n // i)
        return s

    total_sum = 0
    found_amicable_numbers = set()

    for num in range(1, limit + 1):
        if num in found_amicable_numbers:
            continue

        d_num = sum_proper_divisors(num)

        # Check if d_num forms an amicable pair with num
        # 1. d_num must be different from num (by definition of amicable numbers)
        # 2. d_num must be within the limit to be included in the sum
        # 3. We only check if num is the smaller number in the pair (d_num > num)
        #    This avoids redundant checks and ensures each pair is processed once.
        if d_num > num and d_num <= limit:
            d_d_num = sum_proper_divisors(d_num)
            if d_d_num == num:
                # Found an amicable pair (num, d_num)
                total_sum += num
                total_sum += d_num
                found_amicable_numbers.add(num)
                found_amicable_numbers.add(d_num)
    return total_sum

