def convert_list_dictionary(*lists):
    if len(lists) < 2:
        return {}

    result_dict = {}

    # zip(*lists) will iterate over elements at the same index from all lists,
    # stopping when the shortest list is exhausted.
    for elements_tuple in zip(*lists):
        # The last element in the tuple is the innermost value
        innermost_value = elements_tuple[-1]

        # Start building the nested dictionary from the inside out
        # The second to last element is the key for the innermost value
        current_nested_dict = {elements_tuple[-2]: innermost_value}

        # Iterate from the third to last element backwards to the first element
        # These elements become the keys for the progressively outer levels
        for i in range(len(elements_tuple) - 3, -1, -1):
            outer_key = elements_tuple[i]
            current_nested_dict = {outer_key: current_nested_dict}

        # The outermost key is the first element of the tuple.
        # Add this fully formed nested dictionary to the main result_dict.
        # current_nested_dict now holds the structure like {'key1': {'key2': ...}}
        # We need to extract the value associated with the outermost key.
        result_dict[elements_tuple[0]] = current_nested_dict[elements_tuple[0]]

    return result_dict

