def find_ways(n, values):
    if n == 0:
        return 1
    if not values:
        return 0

    max_val = max(values)
    max_possible_sum = n * max(0, max_val)

    dp = [[0] * (max_possible_sum + 1) for _ in range(n + 1)]

    dp[0][0] = 1

    for i in range(1, n + 1):
        for current_sum in range(max_possible_sum + 1):
            for val in values:
                prev_sum = current_sum - val
                if 0 <= prev_sum <= max_possible_sum:
                    dp[i][current_sum] += dp[i-1][prev_sum]

    total_ways = sum(dp[n])
    return total_ways

