def heap_sort(arr):
    n = len(arr)

    def heapify(arr_local, n_heap_size, i):
        largest = i
        left = 2 * i + 1
        right = 2 * i + 2

        if left < n_heap_size and arr_local[left] > arr_local[largest]:
            largest = left

        if right < n_heap_size and arr_local[right] > arr_local[largest]:
            largest = right

        if largest != i:
            arr_local[i], arr_local[largest] = arr_local[largest], arr_local[i]
            heapify(arr_local, n_heap_size, largest)

    for i in range(n // 2 - 1, -1, -1):
        heapify(arr, n, i)

    for i in range(n - 1, 0, -1):
        arr[i], arr[0] = arr[0], arr[i]
        heapify(arr, i, 0)

    return arr

