def max_sum(arr):
    n = len(arr)

    if n == 0:
        return float('-inf') # No subsequence, so no sum.

    # lis_sum[i] stores the maximum sum of an increasing subsequence ending at arr[i]
    lis_sum = [0] * n
    for i in range(n):
        lis_sum[i] = arr[i]
        for j in range(i):
            if arr[i] > arr[j]:
                lis_sum[i] = max(lis_sum[i], lis_sum[j] + arr[i])

    # lds_sum[i] stores the maximum sum of a decreasing subsequence starting at arr[i]
    lds_sum = [0] * n
    for i in range(n - 1, -1, -1):
        lds_sum[i] = arr[i]
        for j in range(n - 1, i, -1):
            if arr[i] > arr[j]:
                lds_sum[i] = max(lds_sum[i], lds_sum[j] + arr[i])

    # The maximum sum of a bitonic subsequence
    # For each element arr[i], it can be the peak of a bitonic subsequence.
    # The sum would be (LIS ending at arr[i]) + (LDS starting at arr[i]) - arr[i].
    # We subtract arr[i] because it's included in both LIS and LDS sums.
    # This formula correctly handles purely increasing (where lds_sum[i] would be arr[i])
    # and purely decreasing (where lis_sum[i] would be arr[i]) subsequences as well.
    max_bitonic_sum = float('-inf')
    for i in range(n):
        max_bitonic_sum = max(max_bitonic_sum, lis_sum[i] + lds_sum[i] - arr[i])

    return max_bitonic_sum

