def find_longest_repeating_subseq(text: str) -> int:
    n = len(text)

    dp = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, n + 1):
            # If characters match and their original indices are different
            if text[i-1] == text[j-1] and i != j:
                dp[i][j] = 1 + dp[i-1][j-1]
            else:
                # If characters don't match, or if they match but are at the same index
                # (which means we can't use them for a repeating subsequence)
                # take the maximum from previous subproblems
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    return dp[n][n]

