def magic_square_test(square):
    n = len(square)

    if n == 0:
        return False

    # Check if it's a square matrix and calculate the magic constant from the first row
    magic_constant = 0
    for i in range(n):
        if len(square[i]) != n:
            return False
        if i == 0:
            magic_constant = sum(square[i])

    # Check row sums
    for row in square:
        if sum(row) != magic_constant:
            return False

    # Check column sums
    for j in range(n):
        col_sum = 0
        for i in range(n):
            col_sum += square[i][j]
        if col_sum != magic_constant:
            return False

    # Check main diagonal sum
    diag1_sum = 0
    for i in range(n):
        diag1_sum += square[i][i]
    if diag1_sum != magic_constant:
        return False

    # Check anti-diagonal sum
    diag2_sum = 0
    for i in range(n):
        diag2_sum += square[i][n - 1 - i]
    if diag2_sum != magic_constant:
        return False

    return True

