    if n == 0:
        return False

    for row in matrix:
        if len(row) != n:
            return False

    magic_sum = sum(matrix[0])

    for row in matrix:
        if sum(row) != magic_sum:
            return False

    for j in range(n):
        col_sum = 0
        for i in range(n):
            col_sum += matrix[i][j]
        if col_sum != magic_sum:
            return False

    diag1_sum = 0
    for i in range(n):
        diag1_sum += matrix[i][i]
    if diag1_sum != magic_sum:
        return False

    diag2_sum = 0
    for i in range(n):
        diag2_sum += matrix[i][n - 1 - i]
    if diag2_sum != magic_sum:
        return False

    return True

