def count_Set_Bits(n):
    if n == 0:
        return 0

    k = 0
    while (1 << (k + 1)) <= n:
        k += 1

    bits_up_to_2k_minus_1 = k * (1 << (k - 1)) if k > 0 else 0

    msb_contribution = (n - (1 << k) + 1)

    remaining_contribution = count_Set_Bits(n - (1 << k))

    return bits_up_to_2k_minus_1 + msb_contribution + remaining_contribution

