def check_min_heap(arr):
    n = len(arr)

    # An empty array or an array with one element is considered a valid min-heap.
    if n <= 1:
        return True

    # Iterate only through nodes that can have children.
    # These are nodes from index 0 up to (n // 2) - 1.
    for i in range(n // 2):
        left_child_idx = 2 * i + 1
        right_child_idx = 2 * i + 2

        # Check if the current node is greater than its left child (if it exists)
        if left_child_idx < n:
            if arr[i] > arr[left_child_idx]:
                return False

        # Check if the current node is greater than its right child (if it exists)
        if right_child_idx < n:
            if arr[i] > arr[right_child_idx]:
                return False

    # If all checks pass, the array represents a min-heap
    return True

