    n = len(square)

    if n == 0:
        return False

    # Check if it's a square matrix and calculate the expected sum
    expected_sum = 0
    if n > 0:
        if len(square[0]) != n:
            return False
        expected_sum = sum(square[0])
    else:
        return False # Should be caught by n == 0, but good for robustness

    # Check row sums
    for row in square:
        if len(row) != n or sum(row) != expected_sum:
            return False

    # Check column sums
    for col_idx in range(n):
        current_col_sum = 0
        for row_idx in range(n):
            current_col_sum += square[row_idx][col_idx]
        if current_col_sum != expected_sum:
            return False

    # Check main diagonal sum (top-left to bottom-right)
    main_diag_sum = 0
    for i in range(n):
        main_diag_sum += square[i][i]
    if main_diag_sum != expected_sum:
        return False

    # Check anti-diagonal sum (top-right to bottom-left)
    anti_diag_sum = 0
    for i in range(n):
        anti_diag_sum += square[i][n - 1 - i]
    if anti_diag_sum != expected_sum:
        return False

    return True

