def pair_OR_Sum(arr):
    n = len(arr)
    if n < 2:
        return 0

    total_xor_sum = 0

    max_val = 0
    if arr:
        max_val = max(arr)

    max_bits = max_val.bit_length()

    for k in range(max_bits):
        count_set_bits = 0
        for num in arr:
            if (num >> k) & 1:
                count_set_bits += 1

        count_unset_bits = n - count_set_bits

        total_xor_sum += (count_set_bits * count_unset_bits) * (1 << k)

    return total_xor_sum

