def tuple_str_int(tuple_string: str) -> tuple[int, ...]:
    inner_content = tuple_string[1:-1].strip()

    if not inner_content:
        return ()

    elements = []
    for item_str in inner_content.split(','):
        stripped_item = item_str.strip()
        if stripped_item:
            elements.append(int(stripped_item))

    return tuple(elements)

