def floor_Max(func, interval_start, interval_end, num_samples=1000):
    if num_samples <= 0:
        return math.floor(func(interval_start))

    if interval_start >= interval_end:
        return math.floor(func(interval_start))

    max_val = -float('inf')
    step = (interval_end - interval_start) / num_samples

    for i in range(num_samples + 1):
        x = interval_start + i * step
        current_val = func(x)
        if current_val > max_val:
            max_val = current_val

    return math.floor(max_val)

