def Total_Hamming_Distance(n):
    if n < 0:
        return 0 

    sum_of_trailing_zeros = 0

    k = 0
    while (n >> k) > 0:
        count_j_with_k_trailing_zeros = (n >> k) - (n >> (k + 1))
