def sum_of_square(n):
    def binomial_coefficient(n_val, k_val):
        if k_val < 0 or k_val > n_val:
            return 0
        if k_val == 0 or k_val == n_val:
            return 1
        if k_val > n_val // 2:
            k_val = n_val - k_val

        res = 1
        for i in range(k_val):
            res = res * (n_val - i) // (i + 1)
        return res

    # The sum of squares of binomial coefficients identity is:
    # Sum_{k=0 to n} (C(n, k))^2 = C(2n, n)
    return binomial_coefficient(2 * n, n)

