def count_Pairs(arr):
    n = len(arr)
    if n < 2:
        return 0

    total_possible_pairs = n * (n - 1) // 2

    equal_pairs_count = 0

    # Create a frequency map for elements in the array
    counts = {}
    for x in arr:
        counts[x] = counts.get(x, 0) + 1

    # Calculate pairs of equal elements
    for count in counts.values():
        if count > 1:
            equal_pairs_count += count * (count - 1) // 2

    # The number of unequal pairs is total possible pairs minus equal pairs
    return total_possible_pairs - equal_pairs_count

