def two_unique_nums(nums):
    initial_counts = {}
    for num in nums:
        initial_counts[num] = initial_counts.get(num, 0) + 1

    result = []
    kept_counts = {}

    for num in nums:
        initial_count = initial_counts[num]

        # Determine how many instances of 'num' should be kept in the final list.
        # If a number appears once, keep it (it's not a duplicate).
        # If a number appears more than once (is a duplicate), remove two instances of it.
        # This means if it appeared 2 times, keep 0.
