def check_min_heap(arr):
    n = len(arr)

    # An empty array or an array with one element is always a min-heap.
    if n <= 1:
        return True

    # Iterate only through non-leaf nodes.
    # The last non-leaf node is at index (n // 2) - 1.
    for i in range(n // 2):
        parent_val = arr[i]

        # Check left child
        left_child_idx = 2 * i + 1
        if left_child_idx < n:
            if parent_val > arr[left_child_idx]:
                return False

        # Check right child
        right_child_idx = 2 * i + 2
        if right_child_idx < n:
            if parent_val > arr[right_child_idx]:
                return False

    return True

