def radix_sort(arr):
    if not arr:
        return arr

    max_val = max(arr)

    exp = 1
    while max_val // exp > 0:
        count = [0] * 10
        output = [0] * len(arr)

        for i in range(len(arr)):
            digit = (arr[i] // exp) % 10
            count[digit] += 1

        for i in range(1, 10):
            count[i] += count[i - 1]

        for i in range(len(arr) - 1, -1, -1):
            digit = (arr[i] // exp) % 10
            output[count[digit] - 1] = arr[i]
            count[digit] -= 1

        for i in range(len(arr)):
            arr[i] = output[i]

        exp *= 10

    return arr

def radix_sort(arr):
    def counting_sort_for_radix(arr_local, exp_local):
        n = len(arr_local)
        output = [0] * n
        count = [0] * 10

        for i in range(n):
            index = (arr_local[i] // exp_local) % 10
            count[index] += 1

        for i in range(1, 10):
            count[i] += count[i - 1]

        i = n - 1
        while i >= 0:
            index = (arr_local[i] // exp_local) % 10
            output[count[index] - 1] = arr_local[i]
            count[index] -= 1
            i -= 1

        for i in range(n):
            arr_local[i] = output[i]

    if not arr:
        return arr

    max_val = max(arr)

    exp = 1
    while max_val // exp > 0:
        counting_sort_for_radix(arr, exp)
        exp *= 10
    return arr

