        return 0

    exponents = set()
    d = 2
    temp_n = n

    while d * d <= temp_n:
        if temp_n % d == 0:
            count = 0
            while temp_n % d == 0:
                count += 1
                temp_n //= d
            exponents.add(count)
        d += 1

    if temp_n > 1:
