    n = len(arr)
    if n <= 1:
        return arr

    gap = n
    shrink_factor = 1.3
    swapped = True

    while gap > 1 or swapped:
        # Update the gap value
        if gap > 1:
            gap = int(gap / shrink_factor)
            # Ensure gap is at least 1
            if gap < 1:
                gap = 1

        swapped = False
        # Perform a "bubble sort" pass with the current gap
        for i in range(n - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                swapped = True
    return arr

