def camel_to_snake(camel_case_string):
    if not camel_case_string:
        return ""

    snake_case_chars = []
    for i, char in enumerate(camel_case_string):
        if char.isupper():
            if i > 0 and camel_case_string[i-1].islower():
                snake_case_chars.append('_')
            elif i > 0 and camel_case_string[i-1].isupper() and i < len(camel_case_string) - 1 and camel_case_string[i+1].islower():
                snake_case_chars.append('_')
        snake_case_chars.append(char.lower())

    return "".join(snake_case_chars)

