def camel_to_snake(name):
    snake_case = []
    for i, char in enumerate(name):
        if char.isupper():
            # Add an underscore if:
            # 1. It's not the first character AND
            # 2. (The previous character was lowercase or a digit OR
            #    (The previous character was uppercase AND the current character is followed by a lowercase character))
            if i > 0 and (name[i-1].islower() or name[i-1].isdigit() or \
                          (name[i-1].isupper() and i + 1 < len(name) and name[i+1].islower())):
                snake_case.append('_')
        snake_case.append(char.lower())
    return "".join(snake_case)

def counting_sort(arr):
    if not arr:
        return []

    max_element = arr[0]
    for i in range(1, len(arr)):
        if arr[i] > max_element:
            max_element = arr[i]

    count = [0] * (max_element + 1)

    for num in arr:
        count[num] += 1

    for i in range(1, len(count)):
        count[i] += count[i - 1]

    output = [0] * len(arr)

