def count_Pairs(arr):
    n = len(arr)
    if n < 2:
        return 0

    # Count frequencies of each element
    counts = {}
    for x in arr:
        counts[x] = counts.get(x, 0) + 1

    # Total possible pairs (i, j) where i < j
    total_pairs = n * (n - 1) // 2

    # Calculate pairs where elements are equal
    equal_pairs = 0
    for count in counts.values():
        if count > 1:
            equal_pairs += count * (count - 1) // 2

    # Unequal pairs = Total pairs - Equal pairs
    unequal_pairs = total_pairs - equal_pairs
    return unequal_pairs

