def cal_sum(n):
    if n <= 0:
        return 0
    if n == 1:
        return 3  # P(0)
    if n == 2:
        return 3  # P(0) + P(1)
    if n == 3:
        return 5  # P(0) + P(1) + P(2)

    # Initialize the first three Perrin numbers
    p0 = 3  # P(0)
    p1 = 0  # P(1)
    p2 = 2  # P(2)

    # Sum of the first three numbers
    total_sum = p0 + p1 + p2 

    # Calculate P(3) to P(n-1) and add them to the sum
    # The loop runs for i from 3 up to n-1
    for i in range(3, n):
        # P(i) = P(i-2) + P(i-3)
        # In our variables, this translates to p_current = p1 + p0
        p_current = p1 + p0
        total_sum += p_current

        # Shift values for the next iteration:
        # The old P(1) becomes the new P(0)
        # The old P(2) becomes the new P(1)
        # The current P(i) becomes the new P(2)
        p0 = p1
        p1 = p2
        p2 = p_current

    return total_sum

