    # Initialize the first three Perrin numbers
    p0 = 3  # P(0)
    p1 = 0  # P(1)
    p2 = 2  # P(2)

    # Initialize sum with the first three Perrin numbers
    current_sum = p0 + p1 + p2

    # Calculate subsequent Perrin numbers and add to sum
    # We need to calculate P(3) up to P(n-1)
    for _ in range(3, n):
        p_next = p0 + p1  # P(k) = P(k-2) + P(k-3)
        current_sum += p_next

        # Shift values for the next iteration
        p0 = p1
        p1 = p2
        p2 = p_next

    return current_sum

