def areEquivalent(num1, num2):
    def get_sum_of_divisors(n):
        if n == 0:
            return 0 # Or handle as an error/specific case, assuming positive integers

        total_sum = 0
        # Iterate from 1 up to the square root of n
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                # i is a divisor
                total_sum += i
                # If i*i is not n, then n/i is another distinct divisor
                if i * i != n:
                    total_sum += n // i
        return total_sum

    sum_divisors_num1 = get_sum_of_divisors(num1)
    sum_divisors_num2 = get_sum_of_divisors(num2)

    return sum_divisors_num1 == sum_divisors_num2

def areEquivalent(num1, num2):
    def _get_sum_of_divisors(n):
        if n <= 0:
            return 0 # Sum of divisors is typically defined for positive integers.
                     # Returning 0 for non-positive inputs as a default.
        s = 0
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                s += i
                if i * i != n:
                    s += n // i
        return s

    sum_divisors_num1 = _get_sum_of_divisors(num1)
    sum_divisors_num2 = _get_sum_of_divisors(num2)

    if sum_divisors_num1 == sum_divisors_num2:
        return "Yes"
    else:
        return "No"

