        return 0

    count = 0
    n = num

    i = 2
    while i * i <= n:
        if n % i == 0:
            current_power_count = 0
            while n % i == 0:
                current_power_count += 1
                n //= i
            count += current_power_count
        i += 1

    if n > 1:
        count += 1

    return count

def count_Fac(n):
    if n <= 1:
        return 0

    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    total_count = 0
    for exponent in factors.values():
        total_count += exponent

    return total_count

