def remove_parenthesis(s):
    result = []
    parenthesis_level = 0
    for char in s:
        if char == '(':
            parenthesis_level += 1
        elif char == ')':
            if parenthesis_level > 0:
                parenthesis_level -= 1
            else: # Unmatched closing parenthesis, keep it
                result.append(char)
        else: # Not a parenthesis character
            if parenthesis_level == 0:
                result.append(char)
    return "".join(result)

