def count_duplic(list_of_numbers):
    result = {}
    if not list_of_numbers:
        return result

    current_element = list_of_numbers[0]
    current_count = 1

    for i in range(1, len(list_of_numbers)):
        num = list_of_numbers[i]
        if num == current_element:
            current_count += 1
        else:
            if current_element not in result:
                result[current_element] = []
            result[current_element].append(current_count)

            current_element = num
            current_count = 1

    # Add the count for the last consecutive block
    if current_element not in result:
        result[current_element] = []
    result[current_element].append(current_count)

    return result

def count_duplic(numbers):
    if not numbers:
        return []

    result = []
    current_element = numbers[0]
    current_count = 0

    for i in range(len(numbers)):
        if numbers[i] == current_element:
            current_count += 1
        else:
            result.append((current_element, current_count))
            current_element = numbers[i]
            current_count = 1

    # Append the last sequence after the loop finishes
    result.append((current_element, current_count))

    return result

