def find_length(s: str) -> int:
    if not s:
        return 0

    nums = []
    for char in s:
        if char == '0':
            nums.append(1)
        else:  # char == '1'
            nums.append(-1)

    max_so_far = nums[0]
    current_max = nums[0]

    for i in range(1, len(nums)):
        current_max = max(nums[i], current_max + nums[i])
        max_so_far = max(max_so_far, current_max)

    return max_so_far

