def max_sum(A):
    n = len(A)

    if n == 0:
        return 0
    if n == 1:
        return A[0]

    # msis[i] stores the maximum sum of an increasing subsequence ending at A[i]
    msis = list(A)
    for i in range(1, n):
        for j in range(i):
            if A[i] > A[j]:
                msis[i] = max(msis[i], msis[j] + A[i])

    # msds[i] stores the maximum sum of a decreasing subsequence starting at A[i]
    # This is computed by iterating backwards and finding the maximum sum of an
    # increasing subsequence if we consider elements from right to left.
    msds = list(A)
    for i in range(n - 2, -1, -1):
        for j in range(n - 1, i, -1):
            if A[i] > A[j]:
                msds[i] = max(msds[i], msds[j] + A[i])

    # The maximum sum of a bi-tonic subsequence is found by considering each element A[i]
    # as the peak of a bi-tonic subsequence.
    # The sum for a peak A[i] would be (max sum increasing ending at A[i]) +
    # (max sum decreasing starting at A[i]) - A[i].
    # A[i] is subtracted because it is included in both msis[i] and msds[i].
    max_bi_tonic_sum = float('-inf')
    for i in range(n):
        max_bi_tonic_sum = max(max_bi_tonic_sum, msis[i] + msds[i] - A[i])

    return max_bi_tonic_sum

def max_sum(arr):
    n = len(arr)

    if n == 0:
        return 0
    if n == 1:
        return arr[0]

    lis_sum = [0] * n
    for i in range(n):
        lis_sum[i] = arr[i]
        for j in range(i):
            if arr[i] > arr[j]:
                lis_sum[i] = max(lis_sum[i], lis_sum[j] + arr[i])

    lds_sum = [0] * n
    for i in range(n - 1, -1, -1):
        lds_sum[i] = arr[i]
        for j in range(n - 1, i, -1):
            if arr[i] > arr[j]:
                lds_sum[i] = max(lds_sum[i], lds_sum[j] + arr[i])

    max_bi_tonic_sum = float('-inf') # Initialize with negative infinity to handle all negative numbers correctly

    for i in range(n):
        current_sum = lis_sum[i] + lds_sum[i] - arr[i]
        max_bi_tonic_sum = max(max_bi_tonic_sum, current_sum)

    return max_bi_tonic_sum

def max_sum(arr):
    n = len(arr)

    if n == 0:
        return 0

    # inc_sum[i] stores the maximum sum of an increasing subsequence ending at arr[i]
    inc_sum = [0] * n
    for i in range(n):
        inc_sum[i] = arr[i]
        for j in range(i):
            if arr[i] > arr[j]:
                inc_sum[i] = max(inc_sum[i], inc_sum[j] + arr[i])

    # dec_sum[i] stores the maximum sum of a decreasing subsequence starting at arr[i]
    dec_sum = [0] * n
    for i in range(n - 1, -1, -1):
        dec_sum[i] = arr[i]
        for j in range(n - 1, i, -1):
            if arr[i] > arr[j]:
                dec_sum[i] = max(dec_sum[i], dec_sum[j] + arr[i])

    # The maximum sum of a bitonic subsequence
    # Initialize with negative infinity to correctly handle cases where all sums are negative
    max_bitonic_sum = float('-inf') 

    for i in range(n):
        # For each element arr[i], it can be the peak of a bitonic subsequence.
        # The sum is (max increasing subsequence ending at arr[i]) +
        # (max decreasing subsequence starting at arr[i]) - arr[i]
        # (arr[i] is subtracted because it's counted twice, once in inc_sum[i] and once in dec_sum[i])
