def sum_of_odd_Factors(number):
    if number <= 0:
        return 0

    total_sum = 0
    # Iterate up to the square root of the number
    # We add 1 to include the sqrt itself if it's an integer
    # math.sqrt is assumed to be available (i.e., 'import math' is done at module level)
    limit = int(number**0.5) # Using **0.5 instead of math.sqrt to avoid explicit import within the function definition

    for i in range(1, limit + 1):
        if number % i == 0:
            factor1 = i
            factor2 = number // i

            # Check if factor1 is odd and add it
            if factor1 % 2 != 0:
                total_sum += factor1

            # Check if factor2 is odd and different from factor1
            # This avoids double-counting for perfect squares (e.g., for number=9, i=3, factor1=3, factor2=3)
            if factor2 % 2 != 0 and factor1 != factor2:
                total_sum += factor2
    return total_sum

