def convert_list_dictionary(*lists):
    if len(lists) < 3:
        # To form a nested dictionary with this interpretation,
        # we need at least two lists for keys (outer and inner)
        # and one list for values.
        return {}

    values_list = lists[-1]
    key_lists = lists[:-1]

    result = {}

    # Determine the minimum length among all input lists to avoid IndexError
    min_len = float('inf')
    for lst in lists:
        min_len = min(min_len, len(lst))

    for i in range(min_len):
        current_dict = result
        for j in range(len(key_lists)):
            key = key_lists[j][i]

            if j == len(key_lists) - 1:
                # This is the last key in the path, assign the value
                current_dict[key] = values_list[i]
            else:
                # If the key doesn't exist, create a new dictionary for the next level
                if key not in current_dict:
                    current_dict[key] = {}
                # Move to the next level of nesting
                current_dict = current_dict[key]
    return result

