def convert_list_dictionary(outer_keys, inner_keys, values):
    result = {}
    value_iterator = iter(values)
    for outer_key in outer_keys:
        inner_dict = {}
        for inner_key in inner_keys:
            inner_dict[inner_key] = next(value_iterator)
        result[outer_key] = inner_dict
    return result

def convert_list_dictionary(*lists):
  if not lists:
    return {}

  num_lists = len(lists)
  if num_lists < 2: # Need at least one list for keys and one for values
    return {}

  first_list_len = len(lists[0])
  for lst in lists:
    if len(lst) != first_list_len:
      return {} # All lists must have the same length for parallel mapping

  result_dict = {}

  for i in range(first_list_len):
    current_level = result_dict
    for j in range(num_lists - 1):
      key = lists[j][i]
      if j == num_lists - 2: # This is the second-to-last list, its elements are keys for the final values
        value = lists[num_lists - 1][i]
        current_level[key] = value
      else: # This is an intermediate key list
        if key not in current_level:
          current_level[key] = {}
        current_level = current_level[key]

  return result_dict

