def sum_of_square(n):
    def combinations(N, K):
        if K < 0 or K > N:
            return 0
        if K == 0 or K == N:
            return 1
        if K > N // 2:
            K = N - K

        res = 1
        for i in range(K):
            res = res * (N - i) // (i + 1)
        return res

    return combinations(2 * n, n)

