def get_inv_count(arr):
    n = len(arr)
    if n < 2:
        return 0

    temp_arr = [0] * n

    def _merge_sort_and_count(arr, temp_arr, left, right):
        inv_count = 0
        if left < right:
            mid = (left + right) // 2
            inv_count += _merge_sort_and_count(arr, temp_arr, left, mid)
            inv_count += _merge_sort_and_count(arr, temp_arr, mid + 1, right)
            inv_count += _merge_and_count_split_inv(arr, temp_arr, left, mid, right)
        return inv_count

    def _merge_and_count_split_inv(arr, temp_arr, left, mid, right):
        i = left
        j = mid + 1
        k = left
        inv_count = 0

        while i <= mid and j <= right:
            if arr[i] <= arr[j]:
                temp_arr[k] = arr[i]
                i += 1
            else:
                temp_arr[k] = arr[j]
                inv_count += (mid - i + 1)
                j += 1
            k += 1

        while i <= mid:
            temp_arr[k] = arr[i]
            i += 1
            k += 1

        while j <= right:
            temp_arr[k] = arr[j]
            j += 1
            k += 1

        for idx in range(left, right + 1):
            arr[idx] = temp_arr[idx]

        return inv_count

    return _merge_sort_and_count(arr, temp_arr, 0, n - 1)

