def find_Divisor(L, R):
    divisor_counts = collections.defaultdict(int)

    for d in range(1, R + 1):
        start_multiple = d * ((L + d - 1) // d)
        for m in range(start_multiple, R + 1, d):
            divisor_counts[d] += 1

    max_count = -1
    max_divisor = -1

    for divisor, count in divisor_counts.items():
        if count > max_count:
            max_count = count
            max_divisor = divisor
        elif count == max_count:
            if divisor < max_divisor:
                max_divisor = divisor

    return max_divisor

