def amicable_numbers_sum(limit):
    total_sum = 0
    div_sums = [0] * (limit + 1)

    for i in range(2, limit + 1):
        div_sums[i] = 1

    for i in range(2, limit // 2 + 1):
        for j in range(2 * i, limit + 1, i):
            div_sums[j] += i

    found_amicable = set()

    for a in range(2, limit + 1):
        if a in found_amicable:
            continue

        b = div_sums[a]

        if b > a and b <= limit:
            if div_sums[b] == a:
                total_sum += a
                total_sum += b
                found_amicable.add(a)
                found_amicable.add(b)

    return total_sum

