    div_sums = [1] * (limit + 1)

    if limit >= 0:
        div_sums[0] = 0
    if limit >= 1:
        div_sums[1] = 0

    for i in range(2, limit + 1):
        for j in range(2 * i, limit + 1, i):
            div_sums[j] += i

    total_sum = 0
    amicable_set = set()

    for n in range(1, limit + 1):
        if n in amicable_set:
            continue

        sum_div_n = div_sums[n]

        if sum_div_n > n:
            m = sum_div_n

            if m <= limit:
                sum_div_m = div_sums[m]

                if sum_div_m == n and n != m:
                    total_sum += n
                    amicable_set.add(n)

                    total_sum += m
                    amicable_set.add(m)

    return total_sum

