def two_unique_nums(list_of_lists):
    import collections
    result = []
    for sublist in list_of_lists:
        # Step 1: Determine the target count for each number.
        # Interpretation: If a number appears 'k' times, and k > 2,
        # remove two instances of it (new count becomes k-2).
        # Otherwise (k <= 2), keep its original count.
        original_counts = collections.Counter(sublist)
        target_counts = {}
        for num, count in original_counts.items():
            if count > 2:
                target_counts[num] = count - 2
            else:
                target_counts[num] = count

        # Step 2: Build the new sublist, preserving the original order.
        new_sublist = []
        current_added_counts = collections.defaultdict(int)

        for num in sublist:
            if current_added_counts[num] < target_counts[num]:
                new_sublist.append(num)
                current_added_counts[num] += 1
        result.append(new_sublist)
    return result

