def find_ways(values, length):
    if length < 0:
        return 0

    if length == 0:
        return 1

    if not values:
        return 0

    max_val_in_values = max(values)
    max_sum_bound = length * max(0, max_val_in_values)

    dp = [[0] * (max_sum_bound + 1) for _ in range(length + 1)]

    dp[0][0] = 1

    for i in range(1, length + 1):
        for current_sum in range(max_sum_bound + 1):
            for val in values:
                prev_sum = current_sum - val

                if 0 <= prev_sum <= max_sum_bound:
                    dp[i][current_sum] += dp[i-1][prev_sum]

    total_ways = sum(dp[length])
    return total_ways

