    dp_prev = [0] * (max_sum_bound + 1)
    dp_prev[0] = 1

    for _ in range(1, n + 1):
        dp_current = [0] * (max_sum_bound + 1)
        for s in range(max_sum_bound + 1):
            for val in values:
                prev_s = s - val
                if 0 <= prev_s <= max_sum_bound:
                    dp_current[s] += dp_prev[prev_s]
        dp_prev = dp_current 

