    count = 0
    processed_pairs = set()

    for current_tuple in s:
        a, b = current_tuple

        if a == b:
            continue 

        reversed_tuple = (b, a)

        if reversed_tuple in s:
            canonical_pair = frozenset({current_tuple, reversed_tuple})

            if canonical_pair not in processed_pairs:
