  gap = n
  shrink_factor = 1.3
  swapped = True

  while gap > 1 or swapped:
    if gap > 1:
      gap = int(gap / shrink_factor)
      if gap < 1:
        gap = 1

    swapped = False
    for i in range(n - gap):
      if arr[i] > arr[i + gap]:
        arr[i], arr[i + gap] = arr[i + gap], arr[i]
        swapped = True
  return arr

