def check_abundant(n):
    if n <= 0:
        return False

    # 1 is not abundant (sum of proper divisors is 0)
    # The smallest abundant number is 12.
    if n == 1:
        return False

    sum_proper_divisors = 1  # 1 is always a proper divisor for n > 1

    # Iterate from 2 up to the square root of n to find divisors
    # If 'i' is a divisor, then 'n // i' is also a divisor.
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            sum_proper_divisors += i
            # If i*i == n, then i and n//i are the same (e.g., for n=36, i=6).
            # In this case, we only add it once.
            if i * i != n:
                sum_proper_divisors += n // i

    return sum_proper_divisors > n

