def breakSum(n):
    memo = {}

    def solve(k):
        if k == 0:
            return 0
        if k in memo:
            return memo[k]

        # Option 1: Don't break k, just take k itself
        res_not_broken = k

        # Option 2: Break k into k/2, k/3, k/4 and recursively find their max sums
        # Use integer division for the parts
        res_broken = solve(k // 2) + solve(k // 3) + solve(k // 4)

        # The maximum sum for k is the greater of the two options
        memo[k] = max(res_not_broken, res_broken)
        return memo[k]

    return solve(n)

