    def _breakSum_recursive(k):
        if k == 0:
            return 0
        if k in memo:
            return memo[k]

        # Calculate the sum if we break k into k/2, k/3, k/4
        # The floor division (//) is used as per the problem's implicit integer division.
        broken_sum = _breakSum_recursive(k // 2) + _breakSum_recursive(k // 3) + _breakSum_recursive(k // 4)

        # The result is the maximum of not breaking k (just k itself) or breaking it
        result = max(k, broken_sum)
        memo[k] = result
        return result

    return _breakSum_recursive(n)

