def sum_Of_product(m, n, r):
    def comb(n_val, k_val):
        if n_val < 0:
            return 0
        if k_val < 0 or k_val > n_val:
            return 0
        if k_val == 0 or k_val == n_val:
            return 1
        if k_val > n_val // 2:
            k_val = n_val - k_val

        res = 1
        for i in range(k_val):
            res = res * (n_val - i) // (i + 1)
        return res

    total_sum = 0
    for k in range(r + 1):
        term1 = comb(m, k)
        term2 = comb(n, r - k)
        total_sum += term1 * term2
    return total_sum

