    r_norm = r / 255.0
    g_norm = g / 255.0
    b_norm = b / 255.0

    c_max = max(r_norm, g_norm, b_norm)
    c_min = min(r_norm, g_norm, b_norm)
    delta = c_max - c_min

    h = 0.0
    s = 0.0
    v = c_max

    if delta == 0:
        h = 0.0
    elif c_max == r_norm:
        h = 60 * ((g_norm - b_norm) / delta)
    elif c_max == g_norm:
        h = 60 * ((b_norm - r_norm) / delta + 2)
    elif c_max == b_norm:
        h = 60 * ((r_norm - g_norm) / delta + 4)

    if h < 0:
        h += 360

    if c_max == 0:
        s = 0.0
    else:
        s = delta / c_max

    return (h, s, v)

