def remove_parenthesis(string):
  result = []
  skip_level = 0
  for char in string:
    if char == '(':
      skip_level += 1
    elif char == ')':
      if skip_level > 0:
        skip_level -= 1
    elif skip_level == 0:
      result.append(char)
  return "".join(result)

def remove_parenthesis(s):
    result = []
    parenthesis_depth = 0
    for char in s:
        if char == '(':
            parenthesis_depth += 1
        elif char == ')':
            if parenthesis_depth > 0:
                parenthesis_depth -= 1
            else:
                # Unmatched closing parenthesis, treat as a regular character outside any block
                result.append(char)
        else:
            # Regular character
            if parenthesis_depth == 0:
                result.append(char)
    return "".join(result)

def remove_parenthesis(text_string):
  result_chars = []
  parenthesis_level = 0
  for char in text_string:
    if char == '(':
      parenthesis_level += 1
    elif char == ')':
      if parenthesis_level > 0:
        parenthesis_level -= 1
      else:
        # If parenthesis_level is 0, it's an unmatched closing parenthesis.
        # It's not part of a "parenthesis area" to be removed, so we keep it.
        result_chars.append(char)
    else:
      if parenthesis_level == 0:
        result_chars.append(char)
  return "".join(result_chars)

