    max_divisor = -1

    for d in range(start, end + 1):
        current_count = 0
        for n in range(start, end + 1):
            if n % d == 0:
                current_count += 1

        if current_count > max_occurrence_count:
            max_occurrence_count = current_count
            max_divisor = d
        elif current_count == max_occurrence_count:
            if d < max_divisor:
                max_divisor = d

    return max_divisor

def find_Divisor(start, end):
    divisor_counts = {}

    for num in range(start, end + 1):
        if num == 0:
            continue

        # For finding divisors, we consider the absolute value of num
        # and only count positive divisors.
        abs_num = abs(num)

        # Iterate up to the square root of abs_num to find divisors efficiently
        i = 1
        while i * i <= abs_num:
            if abs_num % i == 0:
                divisor_counts[i] = divisor_counts.get(i, 0) + 1
                if i * i != abs_num:
                    divisor_counts[abs_num // i] = divisor_counts.get(abs_num // i, 0) + 1
            i += 1

    if not divisor_counts:
        return -1

    max_count = -1
    max_divisor = -1 

    # Find the divisor with the maximum count.
    # In case of a tie in counts, choose the smallest divisor.
    for divisor, count in divisor_counts.items():
        if count > max_count:
            max_count = count
            max_divisor = divisor
        elif count == max_count:
            if divisor < max_divisor:
                max_divisor = divisor

    return max_divisor

def find_Divisor(a, b):
    divisor_counts = {}
    for num in range(a, b + 1):
        for d in range(1, num + 1):
            if num % d == 0:
                divisor_counts[d] = divisor_counts.get(d, 0) + 1

    # Find the divisor with the maximum count.
    # In case of a tie in counts, the smallest divisor is chosen.
    # The key for max() is a tuple (count, -divisor).
    # max() prioritizes the first element (count) in descending order.
    # If counts are equal, it prioritizes the second element (-divisor) in descending order,
    # which effectively means choosing the smallest positive divisor.
    max_divisor_item = max(divisor_counts.items(), key=lambda item: (item[1], -item[0]))

    return max_divisor_item[0]

def find_Divisor(a, b):
    max_count = 0
    max_divisor = 0

    for d in range(2, b + 1):
        count_for_d = (b // d) - ((a - 1) // d)

        if count_for_d > max_count:
            max_count = count_for_d
            max_divisor = d

    return max_divisor

