def pancake_sort(arr):
    n = len(arr)

    # Helper function to reverse a sub-array arr[0...k]
    def _flip(sub_arr, k):
        start = 0
        while start < k:
            sub_arr[start], sub_arr[k] = sub_arr[k], sub_arr[start]
            start += 1
            k -= 1

    # Start from the complete array and reduce the current size by one in each iteration
    for current_size in range(n, 1, -1):
        # Find the index of the maximum element in arr[0...current_size-1]
        max_idx = 0
        for i in range(1, current_size):
            if arr[i] > arr[max_idx]:
                max_idx = i

        # If the maximum element is not already at the end of the current sub-array
        if max_idx != current_size - 1:
            # Move the maximum element to the front (index 0)
            _flip(arr, max_idx)

            # Move the maximum element from the front to its correct position
            _flip(arr, current_size - 1)
    return arr

