    total_sum = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            # i is a factor
            if i % 2 != 0:
                total_sum += i

            # Check the other factor (n // i)
            if i * i != n: # Avoid double counting for perfect squares
                other_factor = n // i
                if other_factor % 2 != 0:
                    total_sum += other_factor
        i += 1
    return total_sum

