def is_tree_balanced(root: TreeNode) -> bool:
    def _check_height_and_balance(node):
        # Base case: An empty tree is balanced and has a height of 0.
        if not node:
            return 0

        # Recursively get the height of the left subtree
        left_height = _check_height_and_balance(node.left)
        # If the left subtree is unbalanced (indicated by -1), propagate -1 up
        if left_height == -1:
            return -1

        # Recursively get the height of the right subtree
        right_height = _check_height_and_balance(node.right)
        # If the right subtree is unbalanced (indicated by -1), propagate -1 up
        if right_height == -1:
            return -1

        # Check if the current node is balanced
        # The difference in heights of left and right subtrees must be at most 1
        if abs(left_height - right_height) > 1:
            return -1 # Current node is unbalanced

        # If balanced, return the height of the current subtree
        return 1 + max(left_height, right_height)

    # The tree is balanced if the helper function does not return -1
    return _check_height_and_balance(root) != -1

