    def _flip(sub_arr, k_idx):
        start = 0
        while start < k_idx:
            sub_arr[start], sub_arr[k_idx] = sub_arr[k_idx], sub_arr[start]
            start += 1
            k_idx -= 1

    n = len(arr)
    for curr_size in range(n, 1, -1):
        # Find the index of the maximum element in the current unsorted part (0 to curr_size-1)
        max_idx = 0
        for i in range(1, curr_size):
            if arr[i] > arr[max_idx]:
                max_idx = i

        # If the maximum element is not already at its correct position
        if max_idx != curr_size - 1:
            # 1. Bring the maximum element to the front (index 0)
            # Flip the sub-array from 0 to max_idx
            _flip(arr, max_idx)

            # 2. Place the maximum element at its correct sorted position (curr_size-1)
            # Flip the sub-array from 0 to curr_size-1
            _flip(arr, curr_size - 1)
    return arr

