            if arr_slice[i] > max_val:
                max_val = arr_slice[i]
                max_idx = i
        return max_idx

    def _flip(arr_slice, k):
        start = 0
        end = k
        while start < end:
            arr_slice[start], arr_slice[end] = arr_slice[end], arr_slice[start]
            start += 1
            end -= 1

    for curr_size in range(n, 1, -1):
        max_idx = _find_max_idx(arr, curr_size - 1)

        if max_idx != curr_size - 1:
            _flip(arr, max_idx)
            _flip(arr, curr_size - 1)
    return arr

def pancake_sort(arr):
    n = len(arr)

    def _flip(sub_arr, k):
        start = 0
        end = k
        while start < end:
            sub_arr[start], sub_arr[end] = sub_arr[end], sub_arr[start]
            start += 1
            end -= 1

    def _find_max_idx(sub_arr, k):
        max_val = sub_arr[0]
        max_idx = 0
        for j in range(1, k + 1):
            if sub_arr[j] > max_val:
                max_val = sub_arr[j]
                max_idx = j
        return max_idx

    for i in range(n - 1, 0, -1):
        max_idx = _find_max_idx(arr, i)

        if max_idx != i:
            _flip(arr, max_idx)
            _flip(arr, i)

    return arr

