        return 0

    total_sum = 0

    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        # Check for odd divisors from 3 up to sqrt(num)
        # We only need to check up to the square root of num
        # because if num has a divisor greater than its square root,
        # it must also have a divisor smaller than its square root.
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    for num in range(2, n + 1):
        if is_prime(num):
            total_sum += num

    return total_sum

