def check_expression(expression):
    stack = []
    mapping = {")": "(", "}": "{", "]": "["}
    open_brackets = set(["(", "{", "["])
    close_brackets = set([")", "}", "]"])

    for char in expression:
        if char in open_brackets:
            stack.append(char)
        elif char in close_brackets:
            if not stack:
                return False
            top_element = stack.pop()
            if mapping[char] != top_element:
                return False

    return not stack

