    r_norm = r / 255.0
    g_norm = g / 255.0
    b_norm = b / 255.0

    Cmax = max(r_norm, g_norm, b_norm)
    Cmin = min(r_norm, g_norm, b_norm)
    delta = Cmax - Cmin

    h = 0.0
    s = 0.0
    v = Cmax

    if delta == 0:
        h = 0.0
    elif Cmax == r_norm:
        h = 60 * ((g_norm - b_norm) / delta)
    elif Cmax == g_norm:
        h = 60 * ((b_norm - r_norm) / delta + 2)
    elif Cmax == b_norm:
        h = 60 * ((r_norm - g_norm) / delta + 4)

    if h < 0:
        h += 360

    if Cmax == 0:
        s = 0.0
    else:
        s = delta / Cmax

    return (h, s, v)

