def count_Fac(number):
    exponents = set()

    # Handle factor 2
    count = 0
    while number % 2 == 0:
        count += 1
        number //= 2
    if count > 0:
        exponents.add(count)

    # Handle odd factors
    i = 3
    while i * i <= number:
        count = 0
        while number % i == 0:
            count += 1
            number //= i
        if count > 0:
            exponents.add(count)
        i += 2

    # If number is still greater than 1, it must be a prime factor itself
    # and its exponent is 1
    if number > 1:
        exponents.add(1)

    return len(exponents)

