def count_Fac(n):
    if n <= 1:
        return 0

    distinct_factors = set()

    # Handle factor 2
    while n % 2 == 0:
        distinct_factors.add(2)
        n //= 2

    # Handle odd factors
    # We only need to check up to sqrt(n)
    i = 3
    while i * i <= n:
        while n % i == 0:
            distinct_factors.add(i)
            n //= i
        i += 2

    # If n is a prime number greater than 2 (e.g., 7, or the remaining part of 14 after dividing by 2)
    if n > 2:
        distinct_factors.add(n)

    return len(distinct_factors)

