def max_sum_of_three_consecutive(arr):
    n = len(arr)

    if n == 0:
        return 0
    if n == 1:
        return max(0, arr[0])
    if n == 2:
        return max(0, arr[0], arr[1], arr[0] + arr[1])

    dp_i_minus_3 = arr[0]
    dp_i_minus_2 = arr[0] + arr[1]
    dp_i_minus_1 = max(arr[0] + arr[1], arr[0] + arr[2], arr[1] + arr[2])

    for i in range(3, n):
        current_dp = max(dp_i_minus_1, 
                           dp_i_minus_2 + arr[i], 
                           dp_i_minus_3 + arr[i-1] + arr[i])

        dp_i_minus_3 = dp_i_minus_2
        dp_i_minus_2 = dp_i_minus_1
        dp_i_minus_1 = current_dp

    return max(0, dp_i_minus_1)

