        if num <= 1:
            return 0
        s = 1
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                s += i
                if i * i != num:
                    s += num // i
        return s

    total_sum = 0
    for a in range(1, n + 1):
        sum_div_a = sum_proper_divisors(a)

        if sum_div_a > a and sum_div_a <= n:
            sum_div_b = sum_proper_divisors(sum_div_a)
            if sum_div_b == a:
                total_sum += a
                total_sum += sum_div_a
    return total_sum

