        s = 1
        for i in range(2, int(math.sqrt(n)) + 1):
            if n % i == 0:
                s += i
                if i * i != n:
                    s += n // i
        return s

    total_sum = 0
    found_amicable_numbers = set()

    for a in range(1, limit + 1):
        if a in found_amicable_numbers:
            continue

        b = sum_proper_divisors(a)

        if b > a and b <= limit:
            c = sum_proper_divisors(b)
