    n = len(arr)

    if arr[0] <= arr[n - 1]:
        return arr[n - 1]

    low = 0
    high = n - 1

    while low <= high:
        mid = (low + high) // 2

        if mid < n - 1 and arr[mid] > arr[mid + 1]:
            return arr[mid]

        if mid > 0 and arr[mid] < arr[mid - 1]:
            return arr[mid - 1]

        if arr[low] <= arr[mid]:
            low = mid + 1
        else:
            high = mid - 1

    return arr[0]

