    if number <= 1:
        return 0

    sum_of_primes = 0
    n = number

    # Check for factor 2
    if n % 2 == 0:
        sum_of_primes += 2
        while n % 2 == 0:
            n //= 2

    # Check for odd factors from 3 up to sqrt(n)
    i = 3
    while i * i <= n:
        if n % i == 0:
            sum_of_primes += i
            while n % i == 0:
                n //= i
        i += 2

    # If n is still greater than 1, it must be a prime factor itself
    if n > 1:
        sum_of_primes += n

    return sum_of_primes

