    n = len(arr)

    def heapify(arr_local, n_heap, i):
        largest = i
        l = 2 * i + 1
        r = 2 * i + 2

        if l < n_heap and arr_local[l] > arr_local[largest]:
            largest = l

        if r < n_heap and arr_local[r] > arr_local[largest]:
            largest = r

        if largest != i:
            arr_local[i], arr_local[largest] = arr_local[largest], arr_local[i]
            heapify(arr_local, n_heap, largest)

    for i in range(n // 2 - 1, -1, -1):
        heapify(arr, n, i)

    for i in range(n - 1, 0, -1):
        arr[i], arr[0] = arr[0], arr[i]
        heapify(arr, i, 0)

