def sum(num1, num2):
    import math

    # Calculate the greatest common divisor (GCD) of the two numbers.
    # The common divisors of two numbers are precisely the divisors of their GCD.
    common_divisor_root = math.gcd(num1, num2)

    # Helper function to calculate the sum of divisors for a given number.
    def _sum_divisors(n):
        if n == 0:
            return 0 # Conventionally, the sum of positive divisors of 0 is 0.

        total_sum = 0
        i = 1
        # Iterate up to the square root of n to find divisors efficiently.
        while i * i <= n:
            if n % i == 0:
                total_sum += i
                # If i*i is not equal to n, then n/i is a distinct divisor.
                if i * i != n:
                    total_sum += (n // i)
            i += 1
        return total_sum

    # The sum of common divisors of num1 and num2 is the sum of divisors of their GCD.
    return _sum_divisors(common_divisor_root)

