    def counting_sort_for_radix(arr_to_sort, exp):
        n = len(arr_to_sort)
        output = [0] * n
        count = [0] * 10

        for i in range(n):
            index = (arr_to_sort[i] // exp) % 10
            count[index] += 1

        for i in range(1, 10):
            count[i] += count[i - 1]

        i = n - 1
        while i >= 0:
            index = (arr_to_sort[i] // exp) % 10
            output[count[index] - 1] = arr_to_sort[i]
            count[index] -= 1
            i -= 1

        for i in range(n):
            arr_to_sort[i] = output[i]

