        # Reverses the sublist sub_arr[0...k] in-place
        start = 0
        while start < k:
            sub_arr[start], sub_arr[k] = sub_arr[k], sub_arr[start]
            start += 1
            k -= 1

    n = len(arr)

    for i in range(n - 1, 0, -1):
        # Find the index of the maximum element in arr[0...i]
