        for j in range(1, i + 1):
            if arr[j] > arr[max_idx]:
                max_idx = j

        # If the maximum element is not already in its correct position
        if max_idx != i:
            # 1. Flip to bring the maximum element to the front
            _flip(arr, max_idx)

            # 2. Flip to move the maximum element to its correct sorted position
            _flip(arr, i)
    return arr

