def count_reverse_pairs(string_list):
    counts = {}
    for s in string_list:
        counts[s] = counts.get(s, 0) + 1

    total_pairs = 0
    processed = set()

    for s in counts:
        if s in processed:
            continue

        reversed_s = s[::-1]

        if s == reversed_s:
            # Palindrome case: a string is its own reverse (e.g., "aba")
            # Pairs are formed if there are multiple instances of this palindrome.
            total_pairs += counts[s] // 2
            processed.add(s)
        else:
            # Non-palindrome case: "abc" and "cba"
            if reversed_s in counts:
                # The number of pairs is limited by the minimum count of the string and its reverse.
                total_pairs += min(counts[s], counts[reversed_s])
                processed.add(s)
                processed.add(reversed_s)
            else:
                # If the reverse of 's' is not found, 's' cannot form a pair.
                # Mark 's' as processed to ensure it's not re-evaluated.
                processed.add(s)
    return total_pairs

