def is_tree_balanced(root):
    def _check_balance_and_height(node):
        # Base case: an empty tree is balanced and has height 0
        if not node:
            return 0

        # Recursively get height and balance status of left subtree
        left_height = _check_balance_and_height(node.left)
        # If left subtree is unbalanced (indicated by -1), propagate -1 up
        if left_height == -1:
            return -1

        # Recursively get height and balance status of right subtree
        right_height = _check_balance_and_height(node.right)
        # If right subtree is unbalanced (indicated by -1), propagate -1 up
        if right_height == -1:
            return -1

        # Check if the current node's children heights differ by more than 1
        if abs(left_height - right_height) > 1:
            return -1 # Current subtree is unbalanced

        # If balanced, return the height of the current subtree
        return 1 + max(left_height, right_height)

    # The tree is balanced if the helper function does not return -1 for the root
    return _check_balance_and_height(root) != -1

