def sum(num1, num2):
    common_divisors = []
    limit = min(num1, num2)
    for i in range(1, limit + 1):
        if num1 % i == 0 and num2 % i == 0:
            common_divisors.append(i)
    return __builtins__.sum(common_divisors)

def sum(a, b):
    total_sum = 0
    limit = min(a, b)
    for i in range(1, limit + 1):
        if a % i == 0 and b % i == 0:
            total_sum += i
    return total_sum

def sum(a, b):
    common_divisor_sum = 0
    min_val = min(a, b)
    for i in range(1, min_val + 1):
        if a % i == 0 and b % i == 0:
            common_divisor_sum += i
    return common_divisor_sum

def sum(a, b):
    import math
    g = math.gcd(a, b)
    total_sum = 0
    for i in range(1, int(math.sqrt(g)) + 1):
        if g % i == 0:
            total_sum += i
            if i * i != g:
                total_sum += g // i
    return total_sum

