def cal_sum(n):
    if n <= 0:
        return 0

    p_prev3 = 3
    p_prev2 = 0
    p_prev1 = 2

    if n == 1:
        return p_prev3
    if n == 2:
        return p_prev3 + p_prev2
    if n == 3:
        return p_prev3 + p_prev2 + p_prev1

    current_sum = p_prev3 + p_prev2 + p_prev1

    for _ in range(3, n):
        p_current = p_prev3 + p_prev2
        current_sum += p_current
        p_prev3 = p_prev2
        p_prev2 = p_prev1
        p_prev1 = p_current

    return current_sum

def cal_sum(n):
    if n <= 0:
        return 0
    if n == 1:
        return 3
    if n == 2:
        return 3
    if n == 3:
        return 5

    a = 3
    b = 0
    c = 2

    total_sum = a + b + c

    for i in range(3, n):
        next_perrin = a + b
        total_sum += next_perrin

        a = b
        b = c
        c = next_perrin

    return total_sum

def cal_sum(n):
    if n <= 0:
        return 0
    if n == 1:
        return 3  # P(0)
    if n == 2:
        return 3  # P(0) + P(1)
    if n == 3:
        return 5  # P(0) + P(1) + P(2)

    # Initialize the first three Perrin numbers
    # p_prev_3 corresponds to P(i-3)
    # p_prev_2 corresponds to P(i-2)
    # p_prev_1 corresponds to P(i-1)
    p_prev_3 = 3  # P(0)
    p_prev_2 = 0  # P(1)
    p_prev_1 = 2  # P(2)

    # Sum of P(0), P(1), P(2)
    current_sum = p_prev_3 + p_prev_2 + p_prev_1

    # Calculate subsequent Perrin numbers and add to sum
    # We start from P(3) up to P(n-1)
    for _ in range(3, n):
        p_current = p_prev_3 + p_prev_2
        current_sum += p_current
        # Update for the next iteration
        p_prev_3 = p_prev_2
        p_prev_2 = p_prev_1
        p_prev_1 = p_current

    return current_sum

def camel_to_snake(camel_case_string):
    result = []
    for i, char in enumerate(camel_case_string):
        if char.isupper():
            # Add underscore if the previous character was lowercase (e.g., 'camelCase' -> 'camel_Case')
            if i > 0 and camel_case_string[i-1].islower():
                result.append('_')
            # Add underscore if it's an uppercase letter followed by a lowercase letter,
            # and it's not the first character (e.g., 'APIKey' -> 'API_Key', 'HTTPResponse' -> 'http_response')
            elif i > 0 and i + 1 < len(camel_case_string) and camel_case_string[i+1].islower():
                result.append('_')
            result.append(char.lower())
        else:
            result.append(char)
    return "".join(result)

def power_base_sum(base, power):
    result = base ** power
    sum_digits = 0
    for digit_char in str(result):
        sum_digits += int(digit_char)
    return sum_digits

def sort_dict_item(test_dict):
    def get_product(tup):
        product = 1
        for x in tup:
            product *= x
        return product
    return sorted(test_dict.items(), key=lambda item: get_product(item[0]))
